insert into nexus.tax_rules (code, version, name, category, valid_from, valid_to, parameters, methodology, legal_basis, legal_review_status, change_note) values ('NX-ANM-001', 1, 'Alíquota efetiva de ICMS fora do padrão do NCM', 'ANOMALY', '2006-04-01', null, '{"min_sample": 8, "z_threshold": 3.5, "min_abs_deviation": "0.005", "rate_precision": "0.0001"}'::jsonb, 'Para cada NCM com amostra mínima, calcula a alíquota efetiva (vICMS / vBC) e o desvio robusto (mediana e MAD). Alerta apenas quando |z| supera o limiar E o desvio absoluto é de pelo menos 0,5 p.p. (evita ruído de arredondamento). Não indica, por si só, erro ou valor devido.', 'Método estatístico de priorização (sem base legal própria).', 'NOT_REQUIRED', '') on conflict (code, version) do update set name = excluded.name, parameters = excluded.parameters, methodology = excluded.methodology, legal_basis = excluded.legal_basis, legal_review_status = excluded.legal_review_status, valid_to = excluded.valid_to;
insert into nexus.tax_rules (code, version, name, category, valid_from, valid_to, parameters, methodology, legal_basis, legal_review_status, change_note) values ('NX-CLS-001', 1, 'CFOP de entrada incompatível com a operação', 'CLASSIFICATION', '2006-04-01', null, '{}'::jsonb, 'Na perspectiva do destinatário, CFOP iniciado em 1 = operação interna (mesma UF) e 2 = interestadual. Compara o primeiro dígito escriturado com as UFs do emitente e destinatário.', 'Convênio s/nº de 1970 e Ajuste SINIEF 07/2001 (tabela CFOP).', 'NOT_REQUIRED', '') on conflict (code, version) do update set name = excluded.name, parameters = excluded.parameters, methodology = excluded.methodology, legal_basis = excluded.legal_basis, legal_review_status = excluded.legal_review_status, valid_to = excluded.valid_to;
insert into nexus.tax_rules (code, version, name, category, valid_from, valid_to, parameters, methodology, legal_basis, legal_review_status, change_note) values ('NX-CLS-002', 1, 'NCM divergente entre XML e escrituração', 'CLASSIFICATION', '2006-04-01', null, '{}'::jsonb, 'Compara o NCM do item no XML com o NCM informado na escrituração.', 'Consistência cadastral; a classificação correta deve ser validada por especialista.', 'NOT_REQUIRED', '') on conflict (code, version) do update set name = excluded.name, parameters = excluded.parameters, methodology = excluded.methodology, legal_basis = excluded.legal_basis, legal_review_status = excluded.legal_review_status, valid_to = excluded.valid_to;
insert into nexus.tax_rules (code, version, name, category, valid_from, valid_to, parameters, methodology, legal_basis, legal_review_status, change_note) values ('NX-CLS-003', 1, 'Mesmo produto com NCMs diferentes', 'CLASSIFICATION', '2006-04-01', null, '{}'::jsonb, 'Agrupa itens por (CNPJ do fornecedor, código do produto) e sinaliza quando há mais de um NCM — indício de classificação inconsistente.', 'Consistência cadastral; não conclui qual NCM é o correto.', 'NOT_REQUIRED', '') on conflict (code, version) do update set name = excluded.name, parameters = excluded.parameters, methodology = excluded.methodology, legal_basis = excluded.legal_basis, legal_review_status = excluded.legal_review_status, valid_to = excluded.valid_to;
insert into nexus.tax_rules (code, version, name, category, valid_from, valid_to, parameters, methodology, legal_basis, legal_review_status, change_note) values ('NX-CRD-001', 1, 'ICMS destacado não creditado integralmente', 'CREDIT_OPPORTUNITY', '2006-04-01', null, '{"eligible_cfops": ["1101", "1102", "2101", "2102", "1122", "2122", "1116", "2116"], "excluded_cfops": ["1556", "2556"], "min_amount": "1.00"}'::jsonb, 'Para itens de entrada com CFOP de aquisição para industrialização/comercialização, estimativa = ICMS destacado no XML − ICMS creditado na escrituração. Usa a alíquota e o valor impressos no próprio documento; nenhuma alíquota é presumida.', 'LC 87/1996, arts. 19 e 20 (não cumulatividade e direito ao crédito).', 'RECOMMENDED', '') on conflict (code, version) do update set name = excluded.name, parameters = excluded.parameters, methodology = excluded.methodology, legal_basis = excluded.legal_basis, legal_review_status = excluded.legal_review_status, valid_to = excluded.valid_to;
insert into nexus.tax_rules (code, version, name, category, valid_from, valid_to, parameters, methodology, legal_basis, legal_review_status, change_note) values ('NX-CRD-002', 1, 'ICMS sobre ativo imobilizado não creditado (CIAP)', 'CREDIT_OPPORTUNITY', '2006-04-01', null, '{"eligible_cfops": ["1551", "2551"], "installments": 48}'::jsonb, 'Entradas com CFOP de ativo imobilizado sem crédito escriturado. Estimativa = ICMS destacado × parcelas de 1/48 transcorridas até a última competência analisada (saldo futuro informado à parte). Não aplica o fator de saídas tributadas, desconhecido nos dados. Confiança baixa: depende de controle CIAP e uso do bem.', 'LC 87/1996, art. 20, § 5º (apropriação em 48 parcelas).', 'RECOMMENDED', '') on conflict (code, version) do update set name = excluded.name, parameters = excluded.parameters, methodology = excluded.methodology, legal_basis = excluded.legal_basis, legal_review_status = excluded.legal_review_status, valid_to = excluded.valid_to;
insert into nexus.tax_rules (code, version, name, category, valid_from, valid_to, parameters, methodology, legal_basis, legal_review_status, change_note) values ('NX-CRD-003', 1, 'PIS/COFINS não cumulativo não creditado', 'CREDIT_OPPORTUNITY', '2004-02-01', '2023-04-30', '{"pis_rate": "0.0165", "cofins_rate": "0.0760", "eligible_cfops": ["1101", "1102", "2101", "2102"], "credit_csts": ["50", "51", "52", "53", "54", "55", "56"], "exclude_icms_from_base": false}'::jsonb, 'Aplicável apenas a tenants no regime não cumulativo. Base = valor do item (vProd − vDesc). Estimativa = base × alíquota. Elegibilidade de insumos depende dos critérios de essencialidade/relevância e de exceções (monofásicos, alíquota zero, aquisição de não contribuinte), não verificáveis apenas pelo XML.', 'Lei 10.637/2002, art. 3º (PIS); Lei 10.833/2003, art. 3º (COFINS); STJ, REsp 1.221.170/PR (conceito de insumo).', 'RECOMMENDED', '') on conflict (code, version) do update set name = excluded.name, parameters = excluded.parameters, methodology = excluded.methodology, legal_basis = excluded.legal_basis, legal_review_status = excluded.legal_review_status, valid_to = excluded.valid_to;
insert into nexus.tax_rules (code, version, name, category, valid_from, valid_to, parameters, methodology, legal_basis, legal_review_status, change_note) values ('NX-CRD-003', 2, 'PIS/COFINS não cumulativo não creditado', 'CREDIT_OPPORTUNITY', '2023-05-01', '2026-12-31', '{"pis_rate": "0.0165", "cofins_rate": "0.0760", "eligible_cfops": ["1101", "1102", "2101", "2102"], "credit_csts": ["50", "51", "52", "53", "54", "55", "56"], "exclude_icms_from_base": true}'::jsonb, 'Como a v1, porém a base exclui o ICMS destacado no documento. Vigência encerrada em 31/12/2026 com a extinção de PIS/COFINS e início da CBS.', 'Lei 10.637/2002 e Lei 10.833/2003, art. 3º; exclusão do ICMS da base de crédito: MP 1.159/2023, convertida na Lei 14.592/2023; extinção: EC 132/2023.', 'RECOMMENDED', 'Exclusão do ICMS destacado da base de cálculo do crédito (a partir de 05/2023).') on conflict (code, version) do update set name = excluded.name, parameters = excluded.parameters, methodology = excluded.methodology, legal_basis = excluded.legal_basis, legal_review_status = excluded.legal_review_status, valid_to = excluded.valid_to;
insert into nexus.tax_rules (code, version, name, category, valid_from, valid_to, parameters, methodology, legal_basis, legal_review_status, change_note) values ('NX-CRD-004', 1, 'IPI destacado não creditado', 'CREDIT_OPPORTUNITY', '2006-04-01', null, '{"eligible_cfops": ["1101", "2101", "3101", "1122", "2122"], "min_amount": "1.00"}'::jsonb, 'Aplicável a tenants contribuintes do IPI (estabelecimento industrial). Para itens de entrada com CFOP de compra para industrialização, estimativa = IPI destacado no XML − IPI creditado na escrituração. Usa o valor impresso no documento; nenhuma alíquota da TIPI é presumida. Não verifica se o item é matéria-prima, produto intermediário ou material de embalagem, nem hipóteses de estorno (ex.: emprego em produto isento ou não tributado).', 'Decreto 7.212/2010 (RIPI), art. 226, I (créditos básicos de MP, PI e ME); não cumulatividade do IPI (CF, art. 153, § 3º, II).', 'RECOMMENDED', '') on conflict (code, version) do update set name = excluded.name, parameters = excluded.parameters, methodology = excluded.methodology, legal_basis = excluded.legal_basis, legal_review_status = excluded.legal_review_status, valid_to = excluded.valid_to;
insert into nexus.tax_rules (code, version, name, category, valid_from, valid_to, parameters, methodology, legal_basis, legal_review_status, change_note) values ('NX-DQ-001', 1, 'Chave de acesso inconsistente com o emitente', 'DATA_QUALITY', '2006-04-01', null, '{}'::jsonb, 'Compara o CNPJ embutido na chave de acesso (posições 7–20) com o CNPJ do emitente informado no XML.', 'Leiaute da NF-e — composição da chave de acesso (Manual de Orientação do Contribuinte).', 'NOT_REQUIRED', '') on conflict (code, version) do update set name = excluded.name, parameters = excluded.parameters, methodology = excluded.methodology, legal_basis = excluded.legal_basis, legal_review_status = excluded.legal_review_status, valid_to = excluded.valid_to;
insert into nexus.tax_rules (code, version, name, category, valid_from, valid_to, parameters, methodology, legal_basis, legal_review_status, change_note) values ('NX-DQ-002', 1, 'CNPJ de participante inválido', 'DATA_QUALITY', '2006-04-01', null, '{}'::jsonb, 'Validação do dígito verificador do CNPJ (módulo 11).', 'Algoritmo público de validação do CNPJ (Receita Federal).', 'NOT_REQUIRED', '') on conflict (code, version) do update set name = excluded.name, parameters = excluded.parameters, methodology = excluded.methodology, legal_basis = excluded.legal_basis, legal_review_status = excluded.legal_review_status, valid_to = excluded.valid_to;
insert into nexus.tax_rules (code, version, name, category, valid_from, valid_to, parameters, methodology, legal_basis, legal_review_status, change_note) values ('NX-REC-001', 1, 'NF-e de entrada sem escrituração', 'RECONCILIATION', '2006-04-01', null, '{"min_amount": "0.01"}'::jsonb, 'XML recebido (tenant como destinatário) cuja chave não consta na escrituração fiscal. Valor estimado = ICMS destacado no XML. A elegibilidade ao crédito depende da destinação da mercadoria (não inferível do XML); por isso a confiança é reduzida.', 'LC 87/1996, arts. 19 a 23 (não cumulatividade do ICMS e condições do crédito); obrigatoriedade de escrituração conforme legislação estadual e Guia Prático EFD ICMS/IPI.', 'RECOMMENDED', '') on conflict (code, version) do update set name = excluded.name, parameters = excluded.parameters, methodology = excluded.methodology, legal_basis = excluded.legal_basis, legal_review_status = excluded.legal_review_status, valid_to = excluded.valid_to;
insert into nexus.tax_rules (code, version, name, category, valid_from, valid_to, parameters, methodology, legal_basis, legal_review_status, change_note) values ('NX-REC-002', 1, 'NF-e de saída sem escrituração', 'RECONCILIATION', '2006-04-01', null, '{}'::jsonb, 'XML emitido pelo tenant cuja chave não consta na escrituração. Exposição estimada = ICMS destacado (débito potencialmente não apurado).', 'LC 87/1996, art. 12 (fato gerador); Guia Prático EFD ICMS/IPI (registro C100).', 'NOT_REQUIRED', '') on conflict (code, version) do update set name = excluded.name, parameters = excluded.parameters, methodology = excluded.methodology, legal_basis = excluded.legal_basis, legal_review_status = excluded.legal_review_status, valid_to = excluded.valid_to;
insert into nexus.tax_rules (code, version, name, category, valid_from, valid_to, parameters, methodology, legal_basis, legal_review_status, change_note) values ('NX-REC-003', 1, 'Escrituração sem XML correspondente', 'RECONCILIATION', '2006-04-01', null, '{}'::jsonb, 'Lançamento de entrada na escrituração cuja chave não possui XML na base. Exposição estimada = ICMS creditado sem documento comprobatório disponível.', 'LC 87/1996, art. 23 (crédito condicionado à idoneidade da documentação).', 'NOT_REQUIRED', '') on conflict (code, version) do update set name = excluded.name, parameters = excluded.parameters, methodology = excluded.methodology, legal_basis = excluded.legal_basis, legal_review_status = excluded.legal_review_status, valid_to = excluded.valid_to;
insert into nexus.tax_rules (code, version, name, category, valid_from, valid_to, parameters, methodology, legal_basis, legal_review_status, change_note) values ('NX-REC-004', 1, 'Divergência de valor entre XML e escrituração', 'RECONCILIATION', '2006-04-01', null, '{"abs_tolerance": "1.00", "rel_tolerance": "0.005"}'::jsonb, 'Compara, por chave e número do item, o valor líquido do item no XML (vProd − vDesc) com o valor escriturado. Divergência acima da tolerância gera alerta.', 'Verificação de consistência de dados (sem interpretação legal).', 'NOT_REQUIRED', '') on conflict (code, version) do update set name = excluded.name, parameters = excluded.parameters, methodology = excluded.methodology, legal_basis = excluded.legal_basis, legal_review_status = excluded.legal_review_status, valid_to = excluded.valid_to;
insert into nexus.tax_rules (code, version, name, category, valid_from, valid_to, parameters, methodology, legal_basis, legal_review_status, change_note) values ('NX-REC-005', 1, 'Item da NF-e não escriturado', 'RECONCILIATION', '2006-04-01', null, '{}'::jsonb, 'Documento escriturado parcialmente: item presente no XML e ausente na escrituração. Valor estimado = ICMS destacado do item.', 'LC 87/1996, arts. 19 a 23.', 'RECOMMENDED', '') on conflict (code, version) do update set name = excluded.name, parameters = excluded.parameters, methodology = excluded.methodology, legal_basis = excluded.legal_basis, legal_review_status = excluded.legal_review_status, valid_to = excluded.valid_to;
insert into nexus.tax_rules (code, version, name, category, valid_from, valid_to, parameters, methodology, legal_basis, legal_review_status, change_note) values ('NX-REC-006', 1, 'Divergência escrituração × contabilidade', 'RECONCILIATION', '2006-04-01', null, '{"abs_tolerance": "1.00"}'::jsonb, 'Por período e tributo, compara o total de créditos escriturados com a movimentação a débito nas contas contábeis de tributos a recuperar mapeadas pelo cliente.', 'Verificação de consistência entre registros fiscais e contábeis.', 'NOT_REQUIRED', '') on conflict (code, version) do update set name = excluded.name, parameters = excluded.parameters, methodology = excluded.methodology, legal_basis = excluded.legal_basis, legal_review_status = excluded.legal_review_status, valid_to = excluded.valid_to;
insert into nexus.tax_rules (code, version, name, category, valid_from, valid_to, parameters, methodology, legal_basis, legal_review_status, change_note) values ('NX-RSK-001', 1, 'Crédito de ICMS escriturado maior que o destacado', 'COMPLIANCE_RISK', '2006-04-01', null, '{"abs_tolerance": "0.05"}'::jsonb, 'Crédito escriturado por item acima do ICMS destacado no XML. Exposição = excesso.', 'LC 87/1996, art. 23; crédito limitado ao imposto destacado em documento idôneo.', 'NOT_REQUIRED', '') on conflict (code, version) do update set name = excluded.name, parameters = excluded.parameters, methodology = excluded.methodology, legal_basis = excluded.legal_basis, legal_review_status = excluded.legal_review_status, valid_to = excluded.valid_to;
insert into nexus.tax_rules (code, version, name, category, valid_from, valid_to, parameters, methodology, legal_basis, legal_review_status, change_note) values ('NX-RSK-002', 1, 'Lançamento duplicado na escrituração', 'COMPLIANCE_RISK', '2006-04-01', null, '{}'::jsonb, 'Mesma chave + item escriturados mais de uma vez. Exposição = créditos das ocorrências excedentes.', 'Verificação de consistência; crédito em duplicidade é indevido.', 'NOT_REQUIRED', '') on conflict (code, version) do update set name = excluded.name, parameters = excluded.parameters, methodology = excluded.methodology, legal_basis = excluded.legal_basis, legal_review_status = excluded.legal_review_status, valid_to = excluded.valid_to;
insert into nexus.tax_rules (code, version, name, category, valid_from, valid_to, parameters, methodology, legal_basis, legal_review_status, change_note) values ('NX-RSK-003', 1, 'Crédito sobre documento não autorizado', 'COMPLIANCE_RISK', '2006-04-01', null, '{}'::jsonb, 'Documento com situação diferente de autorizada (cStat ≠ 100/150) escriturado com crédito.', 'LC 87/1996, art. 23 (idoneidade documental).', 'NOT_REQUIRED', '') on conflict (code, version) do update set name = excluded.name, parameters = excluded.parameters, methodology = excluded.methodology, legal_basis = excluded.legal_basis, legal_review_status = excluded.legal_review_status, valid_to = excluded.valid_to;
insert into nexus.tax_rules (code, version, name, category, valid_from, valid_to, parameters, methodology, legal_basis, legal_review_status, change_note) values ('NX-RSK-004', 1, 'Crédito de IPI escriturado maior que o destacado', 'COMPLIANCE_RISK', '2006-04-01', null, '{"abs_tolerance": "0.05"}'::jsonb, 'Crédito de IPI escriturado por item acima do IPI destacado no XML. Exposição = excesso.', 'Decreto 7.212/2010 (RIPI): crédito limitado ao imposto destacado em documento idôneo.', 'NOT_REQUIRED', '') on conflict (code, version) do update set name = excluded.name, parameters = excluded.parameters, methodology = excluded.methodology, legal_basis = excluded.legal_basis, legal_review_status = excluded.legal_review_status, valid_to = excluded.valid_to;
insert into nexus.tax_rules (code, version, name, category, valid_from, valid_to, parameters, methodology, legal_basis, legal_review_status, change_note) values ('NX-RTC-001', 1, 'NF-e sem grupo IBS/CBS (Reforma Tributária)', 'TAX_REFORM', '2026-01-01', null, '{}'::jsonb, 'Documentos emitidos a partir de 01/01/2026 sem informação de IBS/CBS por item. Alerta informativo de prontidão: o cronograma de obrigatoriedade e eventuais dispensas de penalidade devem ser confirmados nas normas e notas técnicas vigentes.', 'EC 132/2023; LC 214/2025; leiaute NF-e com grupo IBS/CBS (NT 2025.002 e atualizações).', 'PENDING', '') on conflict (code, version) do update set name = excluded.name, parameters = excluded.parameters, methodology = excluded.methodology, legal_basis = excluded.legal_basis, legal_review_status = excluded.legal_review_status, valid_to = excluded.valid_to;
insert into nexus.tax_rules (code, version, name, category, valid_from, valid_to, parameters, methodology, legal_basis, legal_review_status, change_note) values ('NX-RTC-002', 1, 'IBS/CBS destacados fora das alíquotas do ano de teste', 'TAX_REFORM', '2026-01-01', '2026-12-31', '{"cbs_rate": "0.009", "ibs_rate": "0.001", "abs_tolerance": "0.05"}'::jsonb, 'Para 2026, compara IBS/CBS destacados com base × alíquotas de teste parametrizadas. Não considera reduções de alíquota, regimes específicos ou dispensas.', 'LC 214/2025 — disposições transitórias para 2026 (CBS 0,9% e IBS 0,1%).', 'PENDING', '') on conflict (code, version) do update set name = excluded.name, parameters = excluded.parameters, methodology = excluded.methodology, legal_basis = excluded.legal_basis, legal_review_status = excluded.legal_review_status, valid_to = excluded.valid_to;
